import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"网络简介实验手册","description":"以地址规划、连通性与抓包实验建立网络实操能力，附待核对版本说明。","frontmatter":{"title":"网络简介实验手册","description":"以地址规划、连通性与抓包实验建立网络实操能力，附待核对版本说明。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"以地址规划、连通性与抓包实验建立网络实操能力，附待核对版本说明。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations"},"next":{"text":"网络互连技术","link":"/life/personal/books/computing/internetworking"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations"},"next":{"text":"网络互连技术","link":"/life/personal/books/computing/internetworking"}},"headers":[],"relativePath":"life/personal/books/computing/network-lab.md","filePath":"life/personal/books/computing/network-lab.md"}'),n={name:"life/personal/books/computing/network-lab.md"};function i(l,e,s,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="网络简介实验手册" tabindex="-1">网络简介实验手册 <a class="header-anchor" href="#网络简介实验手册" aria-label="Permalink to &quot;网络简介实验手册&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书适合与网络理论教材搭配使用。实验手册的价值，在于把“理解定义”推进到“能搭建、能观察、能解释”：同一个拓扑在配置正确与配置错误时会出现怎样的差异，应当保留哪些证据。</p><p>建议为每次实验保存拓扑图、地址表、关键配置、预期结果和实际结果。实验成功不是只留下一个绿色连线，而是能够说明连通性的成立条件。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> 书单中的“网络简介实验手册”可能是完整书名，也可能是某套课程的简称；目前不能据此确定作者、课程版本或实验编号。以下为本站主题导读，不是原书目录。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者与课程版本仍待核对。Cisco Press 的 Introduction to Networks v5.0 Lab Manual 与 v5.1 手册均署名 Cisco Networking Academy，但分属不同课程版本和 ISBN；中文“网络简介实验手册”可能对应其一。机构课程体系提供实验设计依据，不能代替对中文版译者、设备与实验编号的确认。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合已有少量网络概念、希望通过抓包、地址配置与故障实验建立直觉的人。没有设备也可从终端与小型仿真拓扑起步；认证学习者应先核对手册所属课程代次。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>实验关注点</th></tr></thead><tbody><tr><td>实验环境与记录</td><td>认识设备、接口和仿真环境；先记录初始状态，再进行单项修改。</td></tr><tr><td>终端网络信息</td><td>读取地址、掩码、默认网关和 DNS 配置，解释每个字段的用途。</td></tr><tr><td>以太网连通</td><td>搭建小型局域网，观察物理状态、ARP 表与交换机的 MAC 地址表。</td></tr><tr><td>IPv4 子网</td><td>根据主机数量划分地址段，用故意设置的错误掩码检验自己的判断。</td></tr><tr><td>IPv6 基础</td><td>认识链路本地地址与邻居发现，比较其与 IPv4 实验的不同。</td></tr><tr><td>路由与路径</td><td>在多网段拓扑中检查路由选择；区分去程与回程缺少路由的现象。</td></tr><tr><td>报文捕获</td><td>观察 ARP、DNS、ICMP 和 TCP，使用过滤条件缩小证据范围。</td></tr><tr><td>综合故障排查</td><td>一次引入一个故障，记录定位过程、修复动作与恢复后的验证结果。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>实验记录应让别人能够复现，而不只是证明自己点过。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>做一次“错误 DNS 与错误网关”的对照实验，分别记录名称解析、直接访问地址和跨网段通信的差异。可获得的核心能力是把症状与原因区分开，并留下能支持判断的证据。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>步骤明确有助于入门，也可能让人只按顺序点击。建议每次先写预期结果，再改一个条件观察反例；不同课程版本的实验编号和工具默认值不可直接混用。当前未确认本册原目录，不评价其具体编排。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐与一本网络原理教材交替阅读：理论提出预测，实验检查预测，这样记录才会积累成能力。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；应补充封面、版权页或课程编号后，再整理原书逐章介绍。</li><li><a href="https://www.netacad.com/" target="_blank" rel="noopener noreferrer">Cisco Networking Academy</a>：可核对课程归属与配套实验工具，不代表已经确认本书属于其中某版课程。</li><li><a href="https://www.wireshark.org/docs/wsug_html_chunked/" target="_blank" rel="noopener noreferrer">Wireshark 用户指南</a>：抓包实验的补充资料。</li><li><a href="https://www.ciscopress.com/store/introduction-to-networks-v5.0-lab-manual-9781587133121" target="_blank" rel="noopener noreferrer">Cisco Press：v5.0 原版候选</a>：机构作者与版本入口。</li><li><a href="https://www.ciscopress.com/store/introduction-to-networks-lab-manual-v5.1-9781587133534" target="_blank" rel="noopener noreferrer">Cisco Press：v5.1 原版候选</a>：另一版本，不能自动对应中文版。</li></ul>',26)])])}const u=t(n,[["render",i]]);export{k as __pageData,u as default};
